@Bean
IntegrationFlow envioExtMov(P606Properties props, SessionFactory<SftpClient.DirEntry> sftp) {
    // 03000-ENVIA-INTELAR: INTELARSND IN ADMONXFERS
    return IntegrationFlow.from("extmovListo")
            .handle(Sftp.outboundAdapter(sftp)
                    .remoteDirectory(props.salida().directorioRemoto())       // (S151)S151/FILE/INTS/15110S01/...
                    .fileNameGenerator(m -> props.salida().nombre(m.getHeaders())))   // {csi}/EXTMOV{sis}/{fecha}/{hhmmss}/CSV
            .handle(m -> {}, e -> e.advice(registroErrorEnvio()))           // "ERROR EN ENVIO DE ARCHIVO ..." al log
            .get();
}
